use crate::wasi::clocks::wall_clock;

struct Node;

/// 9999-12-31T23:59:59Z. Clamping to this keeps `date` exactly ten characters.
const MAX_SECONDS: u64 = 253_402_300_799;

/// Days since 1970-01-01 to (year, month, day). Howard Hinnant's algorithm.
/// Input must be >= -719468; the callers here only pass non-negative days.
fn civil_from_days(days: i64) -> (i64, u32, u32) {
    let z = days + 719_468;
    let era = z / 146_097;
    let doe = z - era * 146_097; // [0, 146096]
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365; // [0, 399]
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100); // [0, 365]
    let mp = (5 * doy + 2) / 153; // [0, 11], March-based
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32;
    let m = (if mp < 10 { mp + 3 } else { mp - 9 }) as u32;
    let y = if m <= 2 { y + 1 } else { y };
    (y, m, d)
}

impl Guest for Node {
    fn run(_tick: Tick) -> RunInfo {
        let now = wall_clock::now();
        let started = now.seconds;
        let secs = started.min(MAX_SECONDS);
        let (y, m, d) = civil_from_days((secs / 86_400) as i64);
        RunInfo {
            date: format!("{:04}-{:02}-{:02}", y, m, d),
            started,
        }
    }
}

export!(Node);
